<script setup lang="ts">import {Link,useForm} from '@inertiajs/vue3';import AdminLayout from '@/Layouts/AdminLayout.vue';import PageMeta from '@/Components/PageMeta.vue';import type {Setting} from '@/types';const props=defineProps<{setting:Setting;keys:string[]}>();const form=useForm({key:props.setting.key,value:Boolean(props.setting.value),is_public:Boolean(props.setting.is_public)});const labels:Record<string,string>={'verification.require_identity_last4':'Exigir últimos cuatro dígitos de identidad','verification.show_patient_name':'Mostrar nombre enmascarado del paciente','verification.show_diagnosis':'Mostrar diagnóstico','privacy.public_doctor_credentials':'Mostrar credencial profesional'};const submit=()=>form.put(route('admin.settings.update',props.setting.id));</script>
<template><AdminLayout title="Editar configuración" eyebrow="Sistema / Configuración"><PageMeta title="Editar configuración" noindex/><section class="admin-content narrow-content"><form class="panel form-panel" @submit.prevent="submit"><div class="field"><label for="key">Parámetro permitido</label><select id="key" v-model="form.key" required><option v-for="key in keys" :key="key" :value="key">{{ labels[key]||key }}</option></select><code class="code-wrap">{{ form.key }}</code><span class="field-error">{{ form.errors.key }}</span></div><div class="setting-switches"><label><input v-model="form.value" type="checkbox"> {{ labels[form.key]||'Valor habilitado' }}</label><label><input v-model="form.is_public" type="checkbox"> Marcar configuración como pública</label></div><p class="privacy-text">Solo se pueden guardar los cuatro valores booleanos autorizados por el servidor. La visibilidad pública no evita las reglas de enmascaramiento de verificación.</p><div class="form-actions"><Link class="button button--outline-small" :href="route('admin.settings.index')">Cancelar</Link><button class="button button--admin" :disabled="form.processing">Guardar configuración</button></div></form></section></AdminLayout></template>
